={{ (() => {
  const templates = {
    ecommerce: 'Find 10 US e-commerce or direct-to-consumer companies with 50-500 employees and $10M-$100M revenue that sell physical products across multiple US states. They should use Shopify Plus, Magento, BigCommerce, or NetSuite. Look for the Controller, CFO, VP Finance, or VP Operations. Find their company website and business email. Include any recent news about expansion, funding, or new warehouse openings.',
    saas: 'Find 10 US SaaS or software companies with 100-1000 employees and $10M-$200M revenue that use Salesforce, Zuora, Stripe, or Chargebee for billing. Look for the Controller, CFO, VP Finance, or Revenue Operations leader. Find their company website and business email. Include any recent news about product launches, funding rounds, or new market expansion.',
    manufacturing: 'Find 10 US manufacturing or wholesale distribution companies with 100-2000 employees and $25M-$500M revenue that use SAP, Oracle ERP, Microsoft Dynamics, or Epicor. Look for the Controller, CFO, Operations Manager, or VP Operations. Find their company website and business email. Include any recent news about new facilities, M&A, or ERP upgrades.',
    multi_region: 'Find 10 US multi-location operations companies with 100-2000 employees owning properties across multiple states. Look for the Director of Multi-Region Ops, VP Real Estate, Operations Manager, or Controller. Find their company website and business email. Include any recent news about portfolio expansion or new acquisitions.'
  };
  const vk = $('Set - Campaign Config').first().json.vertical_key || 'ecommerce';
  return templates[vk] || templates.ecommerce;
})() }}

={{ (() => {
  const vk = ($('Set - Campaign Config (ExampleCo)').first().json.vertical_key || 'ecommerce').toLowerCase();
  const profiles = {
    ecommerce:     { w_revenue: 20, w_expansion: 30, w_platform: 15, w_title: 20, w_signals: 15 },
    saas:          { w_revenue: 25, w_expansion: 20, w_platform: 20, w_title: 20, w_signals: 15 },
    manufacturing: { w_revenue: 20, w_expansion: 35, w_platform: 10, w_title: 20, w_signals: 15 },
    multi_region:  { w_revenue: 15, w_expansion: 40, w_platform: 0,  w_title: 25, w_signals: 20 }
  };
  return JSON.stringify(profiles[vk] || profiles.ecommerce);
})() }}

={{ (() => {
  const states = ($json.states_of_operation || '').split(',').map(s => s.trim()).filter(Boolean);
  if (states.length >= 10) return 100;
  if (states.length >= 5)  return 75;
  if (states.length >= 3)  return 50;
  if (states.length >= 1)  return 25;
  return 0;
})() }}

={{ (() => {
  const rb = ($json.revenue_band || '').toLowerCase();
  if (rb.includes('200m') || rb.includes('200m+')) return 100;
  if (rb.includes('50m') && rb.includes('200m'))   return 85;
  if (rb.includes('10m') && rb.includes('50m'))    return 70;
  if (rb.includes('10m'))                          return 50;
  return 20;
})() }}

={{ (() => {
  const p = ($json.erp_or_billing_platform || '').toLowerCase();
  const high = ['shopify plus','magento','netsuite','sap','oracle','dynamics','zuora','stripe','chargebee'];
  const med  = ['shopify','woocommerce','quickbooks','xero','epicor','infor'];
  if (high.some(x => p.includes(x))) return 100;
  if (med.some(x => p.includes(x)))  return 60;
  return 20;
})() }}

={{ (() => {
  const t = ($json.contact_title || '').toLowerCase();
  if (t.includes('cfo') || t.includes('chief financial')) return 100;
  if (t.includes('controller'))                           return 90;
  if (t.includes('vp finance') || t.includes('finance director')) return 80;
  if (t.includes('dir') && t.includes('operations'))             return 85;
  if (t.includes('operations manager'))                         return 70;
  if (t.includes('ap manager') || t.includes('accounts payable')) return 55;
  if (t.includes('revenue ops'))                         return 60;
  return 30;
})() }}

={{ (() => {
  try {
    const sigs = JSON.parse($json.RECENT_SIGNALS || '[]');
    if (!sigs.length) return 0;
    const highValue = ['expansion','acquisition','funding','erp_migration','ecommerce_launch'];
    const hasHigh = sigs.some(s => highValue.includes(s.type));
    const hasSource = sigs.some(s => s.source && s.source !== 'unknown');
    if (hasHigh && hasSource) return 100;
    if (hasHigh) return 70;
    return 40;
  } catch(e) { return 0; }
})() }}

={{ (() => {
  try {
    const w = JSON.parse($json.icp_weights || '{}');
    const rev  = ($json.revenue_score  || 0) * ((w.w_revenue  || 20) / 100);
    const nex  = ($json.expansion_score    || 0) * ((w.w_expansion    || 30) / 100);
    const plat = ($json.platform_score || 0) * ((w.w_platform || 15) / 100);
    const tit  = ($json.title_score    || 0) * ((w.w_title    || 20) / 100);
    const sig  = ($json.signals_score  || 0) * ((w.w_signals  || 15) / 100);
    return Math.round(rev + nex + plat + tit + sig);
  } catch(e) { return 0; }
})() }}

={{ (() => {
  const s = $json.ICP_SCORE || 0;
  if (s >= 75) return 'HOT';
  if (s >= 50) return 'WARM';
  return 'COLD';
})() }}
